import assert from "node:assert/strict";
import { spawn, execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { chromium } from "playwright";

// App regression checks at the exact original source URL with generated bytes.
// These do not claim that the upstream Imgur file was fetched or decoded.
const source = "https://i.imgur.com/3hhNUKR.mp4";
const origin = "http://localhost:3045";
const directory = await mkdtemp(join(tmpdir(), "waambat-mechanics-native-"));
const videoPath = join(directory, "changing-320x180.mp4");
execFileSync("ffmpeg", [
  "-loglevel",
  "error",
  "-f",
  "lavfi",
  "-i",
  "testsrc2=size=320x180:rate=30",
  "-t",
  "3",
  "-c:v",
  "libx264",
  "-pix_fmt",
  "yuv420p",
  "-movflags",
  "+faststart",
  videoPath,
]);
const bytes = await readFile(videoPath);
const child = spawn(
  "node",
  ["node_modules/next/dist/bin/next", "start", "--port", "3045"],
  {
    env: {
      ...process.env,
      CMS_CONTENT_PROVIDER: "",
      CMS_LOCAL_TEST: "",
      WAAMBAT_PRIVATE_SITE: "0",
    },
    stdio: "ignore",
  },
);
let browser;
const evidence: Record<string, unknown> = {
  upstreamPlaybackVerified: false,
  exactSource: source,
  transport: "Generated native H.264 fixture; other external requests aborted",
};
try {
  for (let attempt = 0; attempt < 100; attempt++) {
    try {
      if ((await fetch(origin)).ok) break;
    } catch {}
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  browser = await chromium.launch({
    executablePath: process.env.CHROMIUM_PATH ?? "/usr/bin/chromium",
    headless: true,
    args: ["--no-sandbox"],
  });
  for (const width of [1512, 390]) {
    const context = await browser.newContext({
      viewport: { width, height: 844 },
    });
    let requests = 0;
    await context.route("**/*", async (route) => {
      if (route.request().url() === source) {
        requests++;
        await route.fulfill({ body: bytes, contentType: "video/mp4" });
      } else if (!route.request().url().startsWith(origin)) await route.abort();
      else await route.continue();
    });
    const page = await context.newPage();
    await page.goto(`${origin}/mechanics`);
    const card = page.locator('[data-artwork="mechanics-original-video-1"]');
    await card.scrollIntoViewIfNeeded();
    await page.waitForFunction(() => {
      const video = document.querySelector(
        '[data-artwork="mechanics-original-video-1"] video',
      ) as HTMLVideoElement;
      return video?.readyState >= 2 && !video.paused && video.currentTime > 0.2;
    });
    const video = card.locator("video");
    const measured = await video.evaluate((element: HTMLVideoElement) => ({
      src: element.currentSrc,
      width: element.videoWidth,
      height: element.videoHeight,
      boxWidth: element.getBoundingClientRect().width,
      boxHeight: element.getBoundingClientRect().height,
    }));
    assert.equal(measured.src, source);
    assert.equal(measured.width, 320);
    assert.equal(measured.height, 180);
    assert.ok(Math.abs(measured.boxWidth / measured.boxHeight - 16 / 9) < 0.01);
    const hash = (buffer: Buffer) =>
      createHash("sha256").update(buffer).digest("hex");
    const frame1 = hash(await video.screenshot());
    await page.waitForTimeout(550);
    const frame2 = hash(await video.screenshot());
    assert.notEqual(frame1, frame2);
    await card
      .getByRole("button", { name: "Pause quantum mechanics", exact: true })
      .click();
    assert.equal(
      await video.evaluate((element: HTMLVideoElement) => element.paused),
      true,
    );
    await card
      .getByRole("button", { name: "Play quantum mechanics", exact: true })
      .click();
    await page.waitForFunction(
      () =>
        !(
          document.querySelector(
            '[data-artwork="mechanics-original-video-1"] video',
          ) as HTMLVideoElement
        )?.paused,
    );
    const loadedRequests = requests;
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    await page.waitForFunction(
      () =>
        (
          document.querySelector(
            '[data-artwork="mechanics-original-video-1"] video',
          ) as HTMLVideoElement
        )?.paused,
    );
    await card.scrollIntoViewIfNeeded();
    await page.waitForFunction(
      () =>
        !(
          document.querySelector(
            '[data-artwork="mechanics-original-video-1"] video',
          ) as HTMLVideoElement
        )?.paused,
    );
    assert.equal(requests, loadedRequests);
    evidence[String(width)] = {
      ...measured,
      changingFrames: true,
      manualPauseResume: true,
      offscreenPause: true,
      repeatRequestsOnReturn: 0,
    };
    await context.close();
  }
  const reduced = await browser.newContext({
    viewport: { width: 390, height: 844 },
    reducedMotion: "reduce",
  });
  let attempts = 0;
  await reduced.route("**/*", async (route) => {
    if (route.request().url() === source) {
      attempts++;
      if (attempts === 1)
        await route.fulfill({
          status: 404,
          body: "Unavailable",
          contentType: "text/plain",
        });
      else await route.fulfill({ body: bytes, contentType: "video/mp4" });
    } else if (!route.request().url().startsWith(origin)) await route.abort();
    else await route.continue();
  });
  const page = await reduced.newPage();
  await page.goto(`${origin}/mechanics`);
  const card = page.locator('[data-artwork="mechanics-original-video-1"]');
  await card.scrollIntoViewIfNeeded();
  assert.equal(await card.locator("video").count(), 0);
  assert.equal(attempts, 0);
  const initial = await card.locator(".artwork-media").boundingBox();
  assert.equal(initial?.height, 150);
  await card
    .getByRole("button", { name: "Play quantum mechanics", exact: true })
    .click();
  await card.getByRole("status").waitFor();
  assert.equal(
    await card
      .getByRole("link", { name: "Open original video" })
      .getAttribute("href"),
    source,
  );
  await card
    .getByRole("button", {
      name: "Retry playback of quantum mechanics",
      exact: true,
    })
    .click();
  await page.waitForFunction(() => {
    const video = document.querySelector(
      '[data-artwork="mechanics-original-video-1"] video',
    ) as HTMLVideoElement;
    return video?.readyState >= 2 && !video.paused;
  });
  evidence.reducedMotionAndError =
    "No initial source; 150px unknown-source fallback; explicit play, honest unavailable state/direct source and successful native retry verified";
  await writeFile(
    "evidence/mechanics-native-check.json",
    JSON.stringify(evidence, null, 2) + "\n",
  );
  console.log(
    "Exact-source native Mechanics wiring, intrinsic dimensions, lifecycle and error/retry checks pass; upstream playback remains unverified",
  );
} finally {
  await browser?.close();
  child.kill("SIGTERM");
  await rm(directory, { recursive: true, force: true });
}
